import XCTest
@testable import CommanderGameKit

/// Shared fixtures generated by the web app
/// (apps/core/tests/game-manager/ios-fixtures.test.ts) from the TypeScript
/// implementation. Each scenario here must reproduce the TypeScript result
/// exactly; when the web behaviour changes on purpose the JSON is regenerated
/// and these tests fail until the Swift port follows.
final class FixtureTests: XCTestCase {
    struct TransformScenario: Decodable {
        let name: String
        let initial: GameState
        let events: [LiveGameEvent]
        let expected: GameState
    }
    struct DiffScenario: Decodable {
        let name: String
        let prev: GameState
        let next: GameState
        let reverse: Bool
        let expected: [GameLogEvent]
    }
    struct StartScenario: Decodable {
        let name: String
        let state: GameState
        let expected: GameLogEvent
    }

    private func load<T: Decodable>(_ file: String) throws -> T {
        let url = try XCTUnwrap(Bundle.module.url(forResource: file, withExtension: "json", subdirectory: "Fixtures"),
                                "missing fixture \(file).json — run UPDATE_IOS_FIXTURES=1 npx vitest run tests/game-manager/ios-fixtures.test.ts in apps/core")
        return try JSONDecoder().decode(T.self, from: Data(contentsOf: url))
    }

    func testTransformsMatchTypeScript() throws {
        let scenarios: [TransformScenario] = try load("transforms")
        XCTAssertGreaterThan(scenarios.count, 50)
        for s in scenarios {
            let actual = GameReducer.fold(s.initial, events: s.events, now: 0)
            XCTAssertEqual(actual, s.expected, "transform fixture failed: \(s.name)\n\(describeDifference(actual, s.expected))")
        }
    }

    func testDiffsMatchTypeScript() throws {
        let scenarios: [DiffScenario] = try load("diffs")
        XCTAssertGreaterThan(scenarios.count, 20)
        for s in scenarios {
            let actual = GameLog.diff(s.prev, s.next, reverse: s.reverse)
            XCTAssertEqual(actual, s.expected, "diff fixture failed: \(s.name)")
        }
    }

    func testGameStartedMatchesTypeScript() throws {
        let scenarios: [StartScenario] = try load("game-started")
        for s in scenarios {
            XCTAssertEqual(GameLog.gameStartedEvent(s.state), s.expected, "game_started fixture failed: \(s.name)")
        }
    }

    /// Fixtures survive a Swift encode → decode round trip, so a log the app
    /// writes to disk reads back identical.
    func testStateAndEventsRoundTripThroughCodable() throws {
        let scenarios: [TransformScenario] = try load("transforms")
        let encoder = JSONEncoder()
        let decoder = JSONDecoder()
        for s in scenarios {
            let state = try decoder.decode(GameState.self, from: encoder.encode(s.expected))
            XCTAssertEqual(state, s.expected, "state round trip: \(s.name)")
            let events = try decoder.decode([LiveGameEvent].self, from: encoder.encode(s.events))
            XCTAssertEqual(events, s.events, "events round trip: \(s.name)")
        }
    }

    private func describeDifference(_ a: GameState, _ b: GameState) -> String {
        var lines: [String] = []
        if a.notes != b.notes { lines.append("notes: \(a.notes.debugDescription) vs \(b.notes.debugDescription)") }
        if a.turnNumber != b.turnNumber { lines.append("turnNumber: \(a.turnNumber) vs \(b.turnNumber)") }
        if a.currentPlayerIdx != b.currentPlayerIdx { lines.append("currentPlayerIdx: \(a.currentPlayerIdx) vs \(b.currentPlayerIdx)") }
        if a.commanderDamage != b.commanderDamage { lines.append("commanderDamage differs") }
        if a.teamNames != b.teamNames { lines.append("teamNames: \(String(describing: a.teamNames)) vs \(String(describing: b.teamNames))") }
        if a.remoteCheckins != b.remoteCheckins { lines.append("remoteCheckins differ") }
        for (i, (x, y)) in zip(a.players, b.players).enumerated() where x != y {
            lines.append("player \(i): \(x) vs \(y)")
        }
        return lines.joined(separator: "\n")
    }
}
